class Solution {
    public boolean isLongPressedName(String name,String typed){
        int i=0;
        for(int j=0;j<typed.length();j++){
            if(i<name.length()&&typed.charAt(j)==name.charAt(i))i++;
            else if(j==0||typed.charAt(j)!=typed.charAt(j-1))return false;
        }
        return i==name.length();
    }
}

code.kotlin:
class Solution {
    fun isLongPressedName(name:String,typed:String):Boolean{
        var i=0;
        for(j in typed.indices){
            if(i<name.length&&typed[j]==name[i])i++ else if(j==0||typed[j]!=typed[j-1])return false
        };
        return i==name.length
    }
}

